import {readFile,writeFile} from 'node:fs/promises';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {homedir} from 'node:os';
const release=JSON.parse(await readFile(`${homedir()}/Library/Application Support/OpenCut Local/current.json`));
const files=execFileSync('git',['ls-files','-z','--cached','--others','--exclude-standard'],{maxBuffer:64*1024**2}).toString().split('\0').filter(Boolean).sort();
const h=createHash('sha256');
for(const file of files){if(file.endsWith('/next-env.d.ts')||!/^(classic\/(apps\/(web|electron\/app)|rust|packages|patches)\/|crates\/|resources\/|Cargo\.(toml|lock)$|classic\/(package\.json|bun\.lock)$)/.test(file))continue;h.update(file);try{h.update(await readFile(file));}catch(e){if(e.code==='ENOENT')h.update('deleted');else throw e;}}
if(h.digest('hex')!==release.fingerprint)throw Error('Production source mismatch');
const data={release:release.id,commit:execFileSync('git',['rev-parse','HEAD']).toString().trim(),exactSource:true,nativeTests:30,webTests:19,liveCleanup:true,liveRepeat:true,tracksPreserved:true,archivePreserved:true,alternativesPreserved:true,liveMessage:'No clear pauses met this duration after protecting the current speech and word boundaries. No cuts applied.'};
await writeFile('.local/take-silence-current-2026-10-29/verification.json',JSON.stringify(data,null,2));console.log(data);
